import {observeViewerLayout} from './viewer-layout.js';
import {paintObjectivePits} from './minimap-objectives.js';
import {powerPlayMarkup,paintPowerPlays} from './power-play-ui.js';
import {scoreboard,mapStateMarkup,paintMap,goldRows,drakeIcons,grubIcons,goldLeadLabels} from './broadcast-hud.js';
import {objectiveDecisionMarkup} from './objective-ui.js';
import {sampleScene,sceneClock,sceneVisibleKills} from './timeline.js';
import {laneWaveMarkup,laneAttackMarkup,laneActionNarration,paintLaneEffects} from './lane-effects.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const clockLabel=seconds=>`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
function titleForKind(kind){return {'finish-push':'넥서스 우선 공성','baron-push':'바론 강화 공성','trade-push':'오브젝트 교환 공성',waveclear:'수비·미니언 정리',opening:'라인 배치',laning:'동시 라인전','lane-transition':'운영 전환','solo-kill':'솔로킬','duo-kill':'바텀 듀오킬',gank:'갱킹',dive:'다이브',skirmish:'소규모 교전',dragon:'드래곤',herald:'협곡의 전령',grubs:'공허 유충',elder:'장로 드래곤',split:'사이드 압박',farm:'자원 확보',trade:'골드 교환',vision:'시야 장악','objective-setup':'오브젝트 판단','baron-setup':'바론 시야',baron:'바론',siege:'공성',teamfight:'한타',flank:'측면 진입',recall:'귀환 · 정비',nexus:'넥서스'}[kind]??'교전';}
export function sceneNarration(scene,progress){
 const lane=laneActionNarration(scene.lanePlayback,progress);if(lane)return lane;
 if(progress>=.8)return scene.text;
 if(['baron-push','trade-push','waveclear'].includes(scene.kind))return scene.push?.baron?'바론 강화 미니언이 전진합니다. 챔피언들이 포탑을 압박하고 수비진이 미니언을 정리합니다.':scene.kind==='trade-push'?'오브젝트를 양보한 팀이 반대편 라인을 밀고 포탑·정글 자원과 시야를 교환합니다.':'수비진이 미니언을 정리하며 구조물 앞에서 공격을 막아냅니다.';
 if(['farm','trade','split','vision','laning','lane-transition'].includes(scene.kind))return scene.text;
 if(scene.objectiveMode==='lane-control')return '하단 웨이브를 밀어 넣은 쪽이 정글러를 드래곤으로 보냅니다. 상대는 라인에 남습니다.';
 if(scene.kind==='solo-kill')return '두 라이너가 웨이브 사이에서 1대1 각을 봅니다.';
 if(scene.kind==='duo-kill')return '원딜과 서포터가 함께 진입해 상대 바텀의 퇴로를 막습니다.';
 if(scene.decisions&&Object.values(scene.decisions).includes('trade'))return '한 팀은 오브젝트로, 다른 팀은 사이드·정글 골드 교환으로 이동합니다.';
 if(scene.kind==='opening')return '탑·미드·바텀과 정글 입구로 챔피언들이 이동합니다.';
 if(scene.kind==='recall')return '챔피언들이 귀환하며 체력을 회복하고 다음 동선을 준비합니다.';
 if(scene.kind==='gank'||scene.kind==='dive')return `${scene.location==='top'?'탑':scene.location==='bot'?'바텀':'미드'} 측면으로 정글러가 접근합니다. 라이너가 퇴로를 좁히며 호응합니다.`;
 if(scene.kind==='baron-setup')return '정글·서포터가 바론 강가에 먼저 진입합니다. 딜러는 라인을 정리하며 합류를 준비합니다.';
 if(['baron','dragon','herald','grubs','elder','objective-setup'].includes(scene.kind))return `${titleForKind(scene.kind)} 둥지로 양 팀이 모입니다. 전방이 진입하고 딜러는 사거리를 유지합니다.`;
 if(scene.kind==='siege')return '전방이 포탑 앞으로 이동하고 원거리 딜러가 뒤에서 공성을 시작합니다.';
 if(scene.kind==='flank')return '측면으로 우회하는 챔피언이 있습니다. 앞뒤에서 진입하며 상대 딜러의 퇴로를 노립니다.';
 if(scene.kind==='nexus')return '승기를 잡은 팀이 적진으로 진입합니다. 남은 챔피언이 넥서스를 지키려 합니다.';
 return '전방 챔피언이 먼저 진입합니다. 딜러와 서포터가 후방에서 교전에 합류합니다.';
}
function killsUntil(timeline,index,progress){return timeline.slice(0,index).flatMap(s=>s.kills).concat(sceneVisibleKills(timeline[index],progress));}
export function riftSvg(c,set,scene){
 const {E,state:s}=c;
 const towers=[...[[80,390],[80,270],[80,130],[140,80],[290,80],[440,80],[150,450],[225,375],[280,320]].map(p=>[...p,'blue']),...[[520,210],[520,335],[520,470],[455,520],[305,520],[160,520],[450,150],[375,225],[320,280]].map(p=>[...p,'red'])];
 return `<svg viewBox="0 0 600 600" class="rift-svg" role="img" aria-label="상황에 따라 챔피언 초상화가 이동하는 소환사의 협곡"><defs><filter id="minimap-blue" color-interpolation-filters="sRGB"><feComponentTransfer><feFuncR type="linear" slope=".5"/><feFuncG type="linear" slope="1.4"/><feFuncB type="linear" slope="1.8"/></feComponentTransfer></filter><filter id="minimap-red" color-interpolation-filters="sRGB"><feComponentTransfer><feFuncR type="linear" slope="1.8"/><feFuncG type="linear" slope=".48"/><feFuncB type="linear" slope=".55"/></feComponentTransfer></filter><linearGradient id="rift-ground" x2="1" y2="1"><stop stop-color="#17332d"/><stop offset="1" stop-color="#122520"/></linearGradient><pattern id="rift-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0v30" stroke="#52755b" stroke-opacity=".07" fill="none"/></pattern><filter id="rift-glow"><feGaussianBlur stdDeviation="4"/></filter>${scene.actors.map((a,i)=>`<clipPath id="champ-clip-${i}"><circle r="17"/></clipPath>`).join('')}</defs><rect x="1" y="1" width="598" height="598" fill="#080d0b"/><image class="summoners-rift-minimap" href="./assets/maps/summoners-rift.png" x="6" y="6" width="588" height="588"/><rect class="minimap-frame" x="4" y="4" width="592" height="592" rx="3" fill="none" stroke="#9d9258" stroke-width="4"/>${set.simulationVersion>=7?mapStateMarkup(set):`<g class="rift-towers">${towers.map(([x,y,side],i)=>`<g class="rift-tower ${side}" data-tower="${i}" transform="translate(${x},${y})"><circle r="11"/><path d="M-6 5v-10h3v-5h6v5h3V5z"/><circle class="tower-range" r="35"/></g>`).join('')}</g>`}${set.simulationVersion>=7?'':`<g class="rift-nexus blue" transform="translate(63 537)"><image href="./assets/structures/icon_ui_nexus_minimap_v2.png" x="-20" y="-20" width="40" height="40" filter="url(#minimap-blue)"/></g><g class="rift-nexus red" transform="translate(537 63)"><image href="./assets/structures/icon_ui_nexus_minimap_v2.png" x="-20" y="-20" width="40" height="40" filter="url(#minimap-red)"/></g>`}<g class="rift-objective baron" transform="translate(205 195)"><image class="pit-baron-art" href="./assets/objectives/baron.png" x="-17" y="-17" width="34" height="34"/><text y="29" text-anchor="middle">BARON</text></g><g class="rift-objective dragon" transform="translate(410 400)"><image class="pit-dragon-art" href="./assets/objectives/ocean.png" x="-17" y="-17" width="34" height="34"/><text y="29" text-anchor="middle">DRAGON</text></g><g class="scene-focus" visibility="${scene.lanePlayback?.quiet?'hidden':'visible'}" transform="translate(${scene.focus.x} ${scene.focus.y})"><circle class="focus-glow" r="${scene.focus.radius}"/><circle r="${scene.focus.radius*.7}"/><text y="${-scene.focus.radius-10}" text-anchor="middle">${esc(scene.title)}</text></g><g class="movement-paths">${scene.actors.map(a=>`<path class="${a.side}" d="${a.path.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ')}"/>`).join('')}</g>${laneWaveMarkup(scene.lanePlayback)}<g class="combat-effects">${scene.lanePlayback?'':scene.kills.map((k,i)=>`<g data-kill-effect="${i}" opacity="0"><line class="skill-projectile" x1="0" y1="0" x2="0" y2="0"/><circle class="skill-impact" r="22"/><text class="damage-number" text-anchor="middle">${200+(i*137)%600}</text></g>`).join('')}</g><g class="champion-units">${scene.actors.map((a,i)=>{const player=s.players[a.id];return `<g class="champion-token ${a.side}" data-player="${esc(a.id)}" data-champion="${a.champion}" transform="translate(${a.from[0]} ${a.from[1]})"><title>${esc(player?.name??a.role)} · ${esc(E.database().champMap[a.champion]?.name)} · ${a.role}</title><circle class="token-recall" r="26"/><circle class="token-ring" r="20"/><image href="./assets/champions/${a.champion}.png" x="-17" y="-17" width="34" height="34" clip-path="url(#champ-clip-${i})"/><rect class="token-health-bg" x="-21" y="-30" width="42" height="5" rx="1"/><rect data-token-hp x="-21" y="-30" width="42" height="5" rx="1"/><text class="token-role" text-anchor="middle" y="34">${esc(player?.name??a.role)}</text><g class="token-death" opacity="0"><path d="m-10-10 20 20m0-20-20 20"/><text y="6" text-anchor="middle">30</text></g></g>`;}).join('')}</g>${laneAttackMarkup(scene.lanePlayback)}<g class="rift-victory" opacity="0"><rect x="150" y="225" width="300" height="130" rx="5"/><text x="300" y="278" text-anchor="middle">VICTORY</text><text x="300" y="320" text-anchor="middle">${set.winner?esc(c.teamName(set.winner)):''}</text></g></svg>`;
}
function sidePlayers(c,set,side){const {E,state:s,img,esc}=c,id=set[side];return `<aside class="spectator-team ${side}"><h2>${esc(c.teamName(id))}</h2>${E.ROLES.map(role=>{const p=set.stats.find(p=>p.team===id&&p.role===role);return `<div class="spectator-player" data-live-player="${esc(p.player)}">${img(p.champion)}<div><strong>${esc(s.players[p.player]?.name??role)}</strong><small>${role} · ${esc(E.database().champMap[p.champion].name)}</small><div class="live-health"><i style="width:100%"></i></div><div class="player-economy"><span class="live-kda">0 / 0 / 0</span><span class="live-level">Lv.1</span><span class="live-cs">CS —</span></div><div class="player-gold-line"><b class="live-player-gold">— G</b><span class="live-player-gap" title="상대 동일 포지션 대비 실제 누적 골드 차이">—</span></div></div></div>`;}).join('')}</aside>`;}
export function viewerMarkup(c){
 const {state:s,ui,btn,badge,esc}=c,{m,set}=c.viewerData();if(!set)return '<div class="empty">기록을 찾을 수 없습니다.</div>';
 const timeline=c.timelineForSet(set),index=Math.min(ui.viewerIndex,timeline.length-1),scene=timeline[index],finished=!set.live&&index===timeline.length-1&&(ui.sceneProgress??0)>=1,decisionReady=set.live&&set.pending&&index===timeline.length-1&&(ui.sceneProgress??0)>=1;
 const score={[set.blue]:0,[set.red]:0};for(const z of m.sets.slice(0,s.viewing.setIndex+(finished?1:0)))score[z.winner]++;
 return `<section class="live-spectator"><div class="spectator-screen"><header class="live-spectator-header"><h1>경기 관전 · ${set.number}세트</h1><span>${esc(m.competition)} · PATCH ${c.E.patchLabel(set.patch)}</span>${badge(finished?'FINAL':'LIVE',finished?'gold':'red')}<span class="live-reconstruction">${set.live?'진행 중 경기 · 운영 선택':'게임 내 주요 장면 재구성'}</span>${btn('집무실','nav','data-id="home"','compact ghost')}</header>${scoreboard(c,set,m,score,clockLabel(scene.second))}${powerPlayMarkup(set)}<div class="spectator-layout">${sidePlayers(c,set,'blue')}<div class="rift-center"><div class="live-rift" data-model="${set.simulationVersion}" data-scene-kind="${scene.kind}">${riftSvg(c,set,scene)}<div class="rift-scene-tag">${esc(titleForKind(scene.kind))}</div></div>${decisionReady?`<div class="rift-decision-overlay">${objectiveDecisionMarkup(c,set)}</div>`:''}</div>${sidePlayers(c,set,'red')}<div class="rift-side"><div class="rift-killfeed" aria-label="최근 처치" aria-live="polite"></div></div></div><div class="broadcast-commentary"><div class="scene-narration"><span>${esc(scene.title)}</span><p id="scene-narration">${esc(sceneNarration(scene,ui.sceneProgress??0))}</p></div></div><div class="objective-bounty-banner" data-bounty-banner role="status" hidden></div><div class="live-playback"><div class="toolbar">${btn(ui.viewerPlaying?'일시 정지':'재생','viewer-play','','compact')}${[1,2,4,8].map(n=>btn(`x${n}`,'viewer-speed',`data-speed="${n}"`,ui.viewerSpeed===n?'compact primary':'compact')).join('')}${btn('다음 장면','viewer-next','','compact')}${finished?btn(ui.replay?'기록실로':m.status==='done'?'시리즈 마치기':'다음 세트 준비','viewer-continue','','compact primary'):btn(set.live?'남은 세트 자동 진행':'세트 결과 보기','viewer-end','','compact ghost')}</div></div><div class="scene-timeline" aria-label="경기 장면 타임라인">${timeline.map((z,i)=>`<button class="${i===index?'active':''} ${i<index?'seen':''}" data-action="viewer-scene" data-index="${i}" ${!ui.replay&&i>index+1?'disabled':''}><small>${clockLabel(z.second)}</small><span>${esc(i<=index?z.title:titleForKind(z.kind))}</span></button>`).join('')}</div></div>${finished?`<section class="panel flush live-results"><div class="panel-head spread"><h2>세트 기록</h2><div class="toolbar">${m.sets.map((z,i)=>btn(`${i+1}세트`,'viewer-set',`data-index="${i}"`,'compact')).join('')}</div></div><div class="table-wrap"><table><thead><tr><th>구단</th><th>선수</th><th>챔피언</th><th>K / D / A</th><th>CS</th><th>골드</th><th>챔피언 피해량</th></tr></thead><tbody>${set.stats.map(p=>`<tr class="${p.team===s.myTeam?'mine':''}"><td>${esc(c.teamName(p.team))}</td><td>${p.role} · ${esc(s.players[p.player]?.name??p.role)}</td><td><span class="player-label">${c.img(p.champion)} ${esc(c.E.database().champMap[p.champion].name)}</span></td><td>${p.k} / ${p.d} / ${p.a}</td><td>${p.cs}</td><td>${Number.isFinite(p.gold)?p.gold.toLocaleString('ko-KR'):'—'}</td><td>${Number.isFinite(p.damage)?p.damage.toLocaleString('ko-KR'):'—'}</td></tr>`).join('')}</tbody></table></div></section>`:''}</section>`;
}
export function paintScene(c){
 observeViewerLayout();
 const {set}=c.viewerData();if(!set)return;const timeline=c.timelineForSet(set),index=Math.min(c.ui.viewerIndex,timeline.length-1),scene=timeline[index],progress=c.ui.sceneProgress??0;
 const actors=sampleScene(scene,progress),map=Object.fromEntries(actors.map(a=>[a.id,a]));
 const dom=document.querySelector('.live-rift');if(!dom)return;
 for(const a of actors){const el=[...dom.querySelectorAll('[data-player]')].find(el=>el.dataset.player===a.id);if(!el)continue;el.setAttribute('transform',`translate(${a.x.toFixed(2)} ${a.y.toFixed(2)})`);el.classList.toggle('dead',a.visibleDeath);el.classList.toggle('recalling',a.recalling);el.querySelector('[data-token-hp]').setAttribute('width',Math.max(0,a.hp)*.42);el.querySelector('.token-death').setAttribute('opacity',a.visibleDeath?'1':'0');el.querySelector('.token-death text').textContent=Math.max(0,Math.ceil(a.deathUntil-sceneClock(scene,progress)));const small=document.querySelector(`[data-live-player="${CSS.escape(a.id)}"]`);if(small){small.classList.toggle('dead',a.visibleDeath);small.querySelector('.live-health i').style.width=a.hp+'%';}}
 if(scene.lanePlayback)paintLaneEffects(dom,scene.lanePlayback,map,progress);
 else for(let i=0;i<scene.kills.length;i++){const k=scene.kills[i],a=map[k.killer],v=map[k.victim],effect=dom.querySelector(`[data-kill-effect="${i}"]`);if(!effect||!a||!v)continue;const at=.48+i*.03,visible=progress>=at&&progress<Math.min(.95,at+.22);effect.setAttribute('opacity',visible?'1':'0');const line=effect.querySelector('line');line.setAttribute('x1',a.x);line.setAttribute('y1',a.y);line.setAttribute('x2',v.x);line.setAttribute('y2',v.y);const circle=effect.querySelector('circle');circle.setAttribute('cx',v.x);circle.setAttribute('cy',v.y);const text=effect.querySelector('text');text.setAttribute('x',v.x);text.setAttribute('y',v.y-38-(progress-at)*40);}
 const kills=killsUntil(timeline,index,progress);const prior=index?timeline[index-1]:null;const lead=(prior?.lead??0)+((scene.lead??0)-(prior?.lead??0))*progress;
 for(const id of [set.blue,set.red]){const n=kills.filter(k=>k.team===id).length;document.querySelectorAll(`[data-team-score="${CSS.escape(id)}"],[data-kills="${CSS.escape(id)}"]`).forEach(el=>el.textContent=n);const actualGold=scene.gold?.[id],beforeGold=prior?.gold?.[id]??2500;
  const gold=Number.isFinite(actualGold)?beforeGold+(actualGold-beforeGold)*progress:2500+sceneClock(scene,progress)/60*1500+(id===set.blue?lead:-lead)/2;
  const el=document.querySelector(`[data-team-gold="${CSS.escape(id)}"]`);if(el)el.textContent=(Math.max(2500,gold)/1000).toFixed(1)+'K' ;const grubs=scene.grubs?(progress>=.8?scene.grubs[id]:prior?.grubs?.[id]??0):'—';document.querySelectorAll(`[data-grub-icons="${CSS.escape(id)}"]`).forEach(el=>{const count=Number.isFinite(grubs)?grubs:null,key=String(count);if(el.dataset.count!==key){el.dataset.count=key;el.innerHTML=grubIcons(count);el.setAttribute('aria-label',count===null?'이전 경기 유충 기록 없음':`공허 유충 ${count}마리 획득`);}});}
 paintPowerPlays(c,set,timeline,index,progress,sceneClock(scene,progress));
 const labels=goldLeadLabels(lead);for(const side of ['blue','red']){const el=document.querySelector(`[data-team-gold-diff="${CSS.escape(set[side])}"]`);if(el){el.textContent=labels[side];el.hidden=!labels[side];el.setAttribute('aria-label',`${c.teamName(set[side])} 총 골드 우위 ${Math.round(Math.abs(lead)).toLocaleString()}G`);}}
 const effectScene=progress>=.8?scene:prior??(scene.kind==='opening'?scene:null),snapshot=effectScene?.objectiveState,second=sceneClock(scene,progress);
 for(const id of [set.blue,set.red]){const el=document.querySelector(`[data-drake-icons="${CSS.escape(id)}"]`);if(el){const html=drakeIcons(snapshot,id);if(el.innerHTML!==html)el.innerHTML=html;}}
 paintObjectivePits(dom,timeline,index,progress,second);
 paintMap(dom,set,scene,prior,progress,second);

 const rift=effectScene?.rift;for(const id of [set.blue,set.red])document.querySelectorAll(`[data-towers="${CSS.escape(id)}"]`).forEach(el=>el.textContent=rift?.towers[id]??'—');
 const economy=goldRows(set,scene,prior,progress);if(economy)for(const p of economy){const row=document.querySelector(`[data-live-player="${CSS.escape(p.player)}"]`),opponent=economy.find(q=>q.team!==p.team&&q.role===p.role);if(!row)continue;row.querySelector('.live-player-gold').textContent=p.gold.toLocaleString()+' G';const gap=p.gold-(opponent?.gold??p.gold),el=row.querySelector('.live-player-gap');el.textContent=(gap>0?'+':'')+gap.toLocaleString()+' G';el.dataset.lead=gap>0?'ahead':gap<0?'behind':'even';row.querySelector('.live-cs').textContent='CS '+p.cs;row.querySelector('.live-level').textContent='Lv.'+p.level;}


 for(const p of set.stats){const el=document.querySelector(`[data-live-player="${CSS.escape(p.player)}"] .live-kda`);if(el)el.textContent=`${kills.filter(k=>k.killer===p.player).length} / ${kills.filter(k=>k.victim===p.player).length} / ${kills.filter(k=>k.assists.includes(p.player)).length}`;}
 const feed=document.querySelector('.rift-killfeed');const key=kills.length+'|'+index;if(feed&&feed.dataset.key!==key){feed.dataset.key=key;feed.innerHTML=kills.slice(-4).reverse().map(k=>`<div class="kill-entry ${k.team===set.blue?'blue':'red'}"><img src="./assets/champions/${k.killerChampion}.png" alt=""> <strong>${esc(c.state.players[k.killer]?.name??'')}</strong><span>${k.elderExecute?'장로 처형':'처치'}</span><img src="./assets/champions/${k.victimChampion}.png" alt=""><strong>${esc(c.state.players[k.victim]?.name??'')}</strong></div>`).join('');}
 const narration=document.querySelector('#scene-narration'),text=sceneNarration(scene,progress);if(narration&&narration.textContent!==text)narration.textContent=text;
 const clock=document.querySelector('#live-clock');if(clock)clock.textContent=clockLabel(sceneClock(scene,progress));
 const victory=dom.querySelector('.rift-victory');victory?.setAttribute('opacity',scene.kind==='nexus'&&progress>.75?'1':'0');
 const objective=dom.querySelector('.rift-objective.'+scene.objective?.kind);if(objective)objective.classList.toggle('captured',progress>=.8);
}
